+/** TEMPORARY TEST ONLY. Remove activation and this file after the local rehearsal.
+ * No env flag, global fetch patch, SQL lifecycle writes, or production fallback.
+ */
+import { readFileSync, appendFileSync, statSync } from 'node:fs';
+import { createHash } from 'node:crypto';
+import type { PrismaClient } from '@prisma/client';
+import type { AdmittedJob } from './operational.repository';
+import type { Outcome } from './transport';
+import type { INSWIntegrationService } from '../services/insw-integration.service';
+import { singleFrozenDocument } from './classification';
+
+const directory = '/tmp/fi1370-20261101';
+const endpoint = 'https://api.insw.go.id/api-prod/inventory/temp/transaksi';
+export async function createLocalFaultRehearsal(db: PrismaClient) {
+  const file = directory + '/plan.json';
+  const stat = statSync(file);
+  if (stat.uid !== process.getuid!() || (stat.mode & 0o077)) throw Error('PRIVATE_PLAN_REQUIRED');
+  const plan = JSON.parse(readFileSync(file, 'utf8')) as {
+    prefix: string; refs: Record<string, string>; expires: number; endpoint: string; cwd: string;
+  };
+  const url = new URL(process.env.DATABASE_URL ?? 'invalid:');
+  const assertEnvironment = () => {
+    if (!['localhost', '127.0.0.1'].includes(url.hostname) || url.port !== '5432'
+      || url.pathname !== '/imaps_db_restore' || plan.endpoint !== endpoint
+      || process.cwd() !== '/home/kabima/projects/nextjs-projects/imaps' || plan.cwd !== process.cwd()
+      || process.env.INSW_1370_USE_TEST_MODE !== 'true' || process.env.INSW_WORKER_ALLOWED_COMPANIES !== '1370'
+      || Date.now() > plan.expires || !/^FI1370-20261101-[A-F0-9]{8}$/.test(plan.prefix)
+      || ['A', 'B', 'C2', 'D'].some(c => plan.refs[c] !== `${plan.prefix}-${c}`)) throw Error('LOCAL_REHEARSAL_GATE');
+  };
+  assertEnvironment();
+  const [runtime] = await db.$queryRaw<{ name: string; host: string; port: number }[]>`
+    SELECT current_database() AS name, host(inet_server_addr()) AS host, inet_server_port() AS port`;
+  if (runtime.name !== 'imaps_db_restore' || runtime.host !== '127.0.0.1' || runtime.port !== 5432) throw Error('LOCAL_DB_REQUIRED');
+  let current: AdmittedJob | undefined;
+  let provenance: string | undefined;
+  let running = false;
+  const log = (event: object) => appendFileSync(directory + '/boundary.jsonl', JSON.stringify({ at: Date.now(), pid: process.pid, ...event }) + '\n', { mode: 0o600 });
+  return {
+    prepare(job: AdmittedJob, finalize: (outcome: Outcome, endedAt: number) => Promise<void>) {
+      assertEnvironment();
+      if (job.company_code !== 1370 || !Object.values(plan.refs).includes(job.wms_reference ?? '')
+        || job.operation !== 'INCOMING' || job.cycle !== 1 || job.intent !== 'SOURCE_COMMIT'
+        || job.max_auto_retry_snapshot !== 10) throw Error('EXACT_REHEARSAL_JOB_REQUIRED');
+      const c = Object.keys(plan.refs).find(c => plan.refs[c] === job.wms_reference)!;
+      if (job.retry_index > (c === 'A' ? 10 : c === 'B' ? 6 : 0)) throw Error('ATTEMPT_LIMIT');
+      current = job; provenance = undefined;
+      return async (outcome: Outcome, endedAt: number) => finalize({ ...outcome,
+        rehearsalProvenance: provenance,
+      } as Outcome, endedAt);
+    },
+    async request(service: INSWIntegrationService, body: string, signal: AbortSignal, onInvoked?: () => void) {
+      assertEnvironment();
+      const job = current;
+      if (!job || running || singleFrozenDocument(JSON.parse(body)) !== job.wms_reference
+        || createHash('sha256').update(body).digest('hex') !== job.payload_sha256) throw Error('BOUNDARY_IDENTITY_GATE');
+      const c = Object.keys(plan.refs).find(c => plan.refs[c] === job.wms_reference)!;
+      running = true;
+      const real = c === 'B' && job.retry_index === 6;
+      provenance = real ? 'REAL_INSW_TEST_RESPONSE' : c === 'D' ? 'SIMULATED_TRANSPORT_FAULT' : 'SIMULATED_REMOTE_REJECTION';
+      const details = { case: c, queue: job.id, attempt: job.attemptId, retry_index: job.retry_index, provenance };
+      try {
+        return await service.requestFrozenTransaction(body, signal, real ? undefined : async target => {
+          if (target !== endpoint) throw Error('TEST_ENDPOINT_REQUIRED');
+          if (c === 'D') throw new TypeError('SIMULATED_TRANSPORT_FAULT', { cause: { code: 'ECONNRESET' } });
+          return new Response(JSON.stringify({ status: false, code: 'SIMULATED_REMOTE_REJECTION',
+            message: c === 'C2' ? 'SIMULATED_REMOTE_REJECTION: validation refusal (test only)'
+              : 'SIMULATED_REMOTE_REJECTION: temporary service refusal; not accepted (test only)', data: null,
+          }), { status: c === 'C2' ? 422 : 503, statusText: 'SIMULATED_REMOTE_REJECTION', headers: { 'content-type': 'application/json' } });
+        }, () => { log({ event: real ? 'actual_fetch_start' : 'simulated_boundary_start', ...details }); onInvoked?.(); });
+      } finally { log({ event: 'headers_or_error_settled', ...details }); running = false; }
+    },
+  };
+}
